INSERT INTO _fleet_sync_transfers(attempt,database,new_epoch,outcome_kind,cancelled_by,granted_epoch,granted_start_epoch,granted_start_sequence,granted_expires_at,pending_transfer,failure_reason,refusal_kind,refusal_last_renewed_at,refusal_last_seen,refusal_gate_code,refusal_gate_detail,refusal_transfer,refusal_migration_state,refusal_store_fingerprint,refusal_holder,refusal_superseded_by,refusal_migration,refusal_store_version,refusal_supported_version,phase_kind,phase_final_epoch,phase_final_sequence) VALUES(?1,?2,NULLIF(?3,'null'),json_extract(?4,'$.kind'),json_extract(?4,'$.value.by'),NULLIF(?4 -> '$.value.epoch','null'),NULLIF(?4 -> '$.value.start.epoch','null'),NULLIF(?4 -> '$.value.start.sequence','null'),json_extract(?4,'$.value.expiresAt'),json_extract(?4,'$.value.transfer'),json_extract(?4,'$.value.reason'),json_extract(?4,'$.value.kind'),json_extract(?4,'$.value.value.lastRenewedAt'),json_extract(?4,'$.value.value.lastSeen'),json_extract(?4,'$.value.value.reason.code'),json_extract(?4,'$.value.value.reason.detail'),json_extract(?4,'$.value.value.transfer'),json_extract(?4,'$.value.value.state'),json_extract(?4,'$.value.value.store.fingerprint'),json_extract(?4,'$.value.value.holder'),json_extract(?4,'$.value.value.by'),NULLIF(?4 -> '$.value.value.migration','null'),NULLIF(?4 -> '$.value.value.store.version','null'),NULLIF(?4 -> '$.value.value.supported','null'),json_extract(?5,'$.phase'),NULLIF(?5 -> '$.finalPosition.epoch','null'),NULLIF(?5 -> '$.finalPosition.sequence','null')) ON CONFLICT(attempt) DO UPDATE SET new_epoch=excluded.new_epoch,outcome_kind=excluded.outcome_kind,cancelled_by=excluded.cancelled_by,granted_epoch=excluded.granted_epoch,granted_start_epoch=excluded.granted_start_epoch,granted_start_sequence=excluded.granted_start_sequence,granted_expires_at=excluded.granted_expires_at,pending_transfer=excluded.pending_transfer,failure_reason=excluded.failure_reason,refusal_kind=excluded.refusal_kind,refusal_last_renewed_at=excluded.refusal_last_renewed_at,refusal_last_seen=excluded.refusal_last_seen,refusal_gate_code=excluded.refusal_gate_code,refusal_gate_detail=excluded.refusal_gate_detail,refusal_transfer=excluded.refusal_transfer,refusal_migration_state=excluded.refusal_migration_state,refusal_store_fingerprint=excluded.refusal_store_fingerprint,refusal_holder=excluded.refusal_holder,refusal_superseded_by=excluded.refusal_superseded_by,refusal_migration=excluded.refusal_migration,refusal_store_version=excluded.refusal_store_version,refusal_supported_version=excluded.refusal_supported_version,phase_kind=excluded.phase_kind,phase_final_epoch=excluded.phase_final_epoch,phase_final_sequence=excluded.phase_final_sequence,updated_at=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER))
